mapper.select:
select oj_comment.resource_id, oj_comment.user_id, oj_comment.content, oj_comment.theme_name, oj_comment.business_type, oj_comment.create_time, oj_comment.root_id, IF(oj_comment.business_type = 2, concat(oj_course_lesson.course_id, '/', oj_course_lesson.resource_id), oj_comment.business_id) as root_business_id from oj_comment left join oj_course_lesson on oj_comment.business_id = oj_course_lesson.resource_id where oj_comment.user_id = #{userId}
and oj_comment.root_id is not null
and oj_comment.root_id is null
and oj_comment.business_id in
#{businessId}

select business_id
from oj_note
where oj_note.`user_id` = #{userId}
  and oj_note.note_type = #{noteType}

select distinct (case when oj_note.business_type = 2 then concat(oj_course_lesson.course_id, '/', oj_course_lesson.resource_id) when oj_note.business_type = 4 then concat(oj_course_lesson.course_id, '/', oj_course_lesson.resource_id,'/',pp.p_resource_id ) else oj_note.business_id end) as business_id, oj_note.user_id, oj_note.content, oj_note.create_time, oj_note.business_type as resource_type, oj_note.note_type, (case when oj_note.business_type = 1 then oj_course.name when oj_note.business_type = 2 then oj_course_lesson.name when oj_note.business_type = 3 then ifnull(oj_practice_operation.title, '') when oj_note.business_type = 4 then pp.name when oj_note.business_type = 5 then ifnull(oj_practice_theory.title, '') END ) as theme_name, oj_practice_theory.theory_type practice_type, ifnull(oj_practice_theory.difficulty, oj_practice_operation.difficulty) difficulty, oj_note.business_type from oj_note left join oj_course_lesson on oj_note.business_id = oj_course_lesson.resource_id left join oj_course on oj_note.business_id = oj_course.resource_id left join oj_practice_operation on oj_note.business_id = oj_practice_operation.resource_id left join oj_practice_theory on oj_note.business_id = oj_practice_theory.resource_id left join (select p.name as name,l.resource_id as resource_id,p.resource_id as p_resource_id from oj_course_lesson l left join oj_paper p on l.paper_id = p.resource_id) pp on pp.resource_id = oj_note.business_id where oj_note.`user_id` = #{userId} and oj_note.note_type = #{noteType}
and oj_note.business_id in
#{businessId}
and business_type = #{businessType}
and business_type != 3
AND oj_practice_theory.theory_type = #{practiceType}
order by oj_note.create_time desc

select resource_id from oj_course_lesson where public = True and course_id in
#{courseId}
('')

select resource_id from oj_course_lesson where public = True and type = 1 and course_id in
#{courseId}
('')

select resource_id from oj_paper where type = 3 and


    and resource_id in

        #{lessonId}

select (case when oj_course_lesson.resource_id is not null then concat(oj_course_lesson.course_id,'/',oj_course_lesson.resource_id) when oj_course.resource_id is not null then oj_course.resource_id when oj_practice_theory.resource_id is not null then oj_practice_theory.resource_id when oj_practice_operation.resource_id is not null then oj_practice_operation.resource_id END) as resource_id from oj_resource_collection left join oj_course on oj_resource_collection.business_id = oj_course.resource_id and oj_resource_collection.business_type = 3 left join oj_course_lesson on oj_resource_collection.business_id = oj_course_lesson.resource_id and oj_resource_collection.business_type = 4 left join oj_practice_theory on oj_resource_collection.business_id = oj_practice_theory.resource_id and oj_resource_collection.business_type = 0 left join oj_practice_operation on oj_resource_collection.business_id = oj_practice_operation.resource_id and oj_resource_collection.business_type = 2 where user_id = #{userId}
and business_type = #{businessType}
and oj_resource_collection.business_id in
#{businessId}
order by oj_resource_collection.create_time desc

select (case when oj_course_lesson.resource_id is not null then concat(oj_course_lesson.course_id,'/',oj_course_lesson.resource_id) -- when oj_course.resource_id is not null then oj_course.resource_id when oj_practice_theory.resource_id is not null then oj_practice_theory.resource_id when oj_practice_operation.resource_id is not null then oj_practice_operation.resource_id END) as resource_id, (case -- when oj_course.name is not null then oj_course.name when oj_course_lesson.name is not null then oj_course_lesson.name when oj_practice_theory.title is not null then oj_practice_theory.title when oj_practice_theory.content is not null then oj_practice_theory.content when oj_practice_operation.title is not null then oj_practice_operation.title when oj_practice_operation.content is not null then oj_practice_operation.content END) as name, oj_resource_collection.create_time, oj_resource_collection.business_type as business_type, oj_practice_theory.theory_type practice_type from oj_resource_collection -- left join oj_course on oj_resource_collection.business_id = oj_course.resource_id and -- oj_resource_collection.business_type = 3 left join oj_course_lesson on oj_resource_collection.business_id = oj_course_lesson.resource_id and oj_resource_collection.business_type = 4 left join oj_practice_theory on oj_resource_collection.business_id = oj_practice_theory.resource_id and oj_resource_collection.business_type = 0 left join oj_practice_operation on oj_resource_collection.business_id = oj_practice_operation.resource_id and oj_resource_collection.business_type = 2 where user_id = #{userId}
and business_type = #{businessType}
and oj_resource_collection.business_id in
#{businessId}
AND oj_practice_theory.theory_type = #{practiceType}
order by oj_resource_collection.create_time desc

select count(distinct oj_course.resource_id) as course_count, SUM(oj_course_lesson.duration) as duration, SUM(case when oj_course_lesson.type = 0 then 1 END)as theory_count , SUM(case when oj_course_lesson.type = 1 then 1 END ) as exp_count from oj_lesson_record left join oj_course on oj_course.resource_id = oj_lesson_record.course_id left join oj_course_lesson on oj_course_lesson.resource_id = oj_lesson_record.lesson_id where oj_lesson_record.user_id = #{userId}
and oj_lesson_record.lesson_id in
#{lessonId}

select count(resource_id) from oj_note
where note_type = 2 and user_id = #{userId}

    and oj_note.business_id in

        #{lessonId}

select submit_user_id,sum(score) as score, row_number() over (order by score desc) as practice_ranking, count(record) as record from oj_lesson_paper_evaluate where submit_user_id = #{userId}
and oj_lesson_paper_evaluate.lesson_id in
#{lessonId}
group by submit_user_id

select create_time,course_id
from oj_lesson_record
where user_id = #{userId}
and create_time > #{startTime}
and create_time < #{endTime}
and oj_lesson_record.lesson_id in


        #{lessonId}



    ('')

select *
from oj_note
where user_id = #{userId} and note_type = 2 and business_type = 2
and resource_id in (select note_id from oj_note_evaluate where score >= 80)
and create_time > #{startTime}
and create_time < #{endTime}

    and oj_note.business_id in

        #{lessonId}

select *
from oj_note_evaluate
where
note_id in (select resource_id from oj_note where user_id = #{userId}
and note_type = 2 and business_type = 2
and oj_note.business_id in


        #{lessonId}



    ('')

)
and score >= 80
and create_time > #{startTime}
and create_time < #{endTime}

select course_name as `name`,
       1 as `type`,
       DATE_FORMAT(create_time, '%Y-%m-%d') as `date`,
       course_id as resourceId
from oj_course_study_history
where user_id = #{userId}
  and create_time >= #{startTime}
  and create_time <= #{endTime}
